const list = document.querySelector("#list")
const names = document.querySelector("#seeds").textContent.split(",").map((s) => s.trim())
for (const name of names) {
  const li = document.createElement("li")
  li.textContent = name
  list.append(li)
}
const q = document.querySelector("#q")
q.addEventListener("input", () => {
  const needle = q.value.toLowerCase()
  for (const li of list.querySelectorAll("li")) li.hidden = !li.textContent.toLowerCase().includes(needle)
})
